mapper.select:
SELECT id, book_id, author_id, status, remark, audit_admin_id, submit_time, audit_time
FROM book_audit_record
WHERE id = #{id}

mapper.update:
UPDATE book_audit_record
SET status = #{status},
    remark = #{remark},
    audit_admin_id = #{auditAdminId},
    audit_time = #{auditTime}
WHERE id = #{id}
